description:
Write `fn tidy(text: &str) -> Cow<'_, str>` that:

- trims spaces and tabs from both ends;
- replaces each run of several spaces or tabs inside the text with one space;
- replaces the "smart" quotes `‘` `’` with `'` and `“` `”` with `"`.

When none of this changes anything, it must return `Cow::Borrowed` of the input itself (no allocation). When only trimming is needed, it must also borrow: return a slice of the input. Only when characters inside the text have to change does it return `Cow::Owned`.

Then write `fn tidy_all<S: AsRef<str>>(lines: &[S]) -> Vec<String>` that tidies every line (of any string type) and drops the lines that end up empty.

starter.solution.rs:
use std::borrow::Cow;

fn tidy(text: &str) -> Cow<'_, str> {
    Cow::Owned(text.to_string())
}

fn tidy_all<S: AsRef<str>>(lines: &[S]) -> Vec<String> {
    Vec::new()
}

solution.solution.rs:
use std::borrow::Cow;

fn needs_rewrite(text: &str) -> bool {
    let mut last_blank = false;
    for c in text.chars() {
        let blank = c == ' ' || c == '\t';
        if blank && (last_blank || c == '\t') { return true; }
        if matches!(c, '‘' | '’' | '“' | '”') { return true; }
        last_blank = blank;
    }
    false
}

fn tidy(text: &str) -> Cow<'_, str> {
    let trimmed = text.trim_matches(|c| c == ' ' || c == '\t');
    if !needs_rewrite(trimmed) {
        return Cow::Borrowed(trimmed);
    }
    let mut out = String::with_capacity(trimmed.len());
    let mut last_blank = false;
    for c in trimmed.chars() {
        let blank = c == ' ' || c == '\t';
        if blank {
            if !last_blank { out.push(' '); }
        } else {
            out.push(match c {
                '‘' | '’' => '\'',
                '“' | '”' => '"',
                other => other,
            });
        }
        last_blank = blank;
    }
    Cow::Owned(out)
}

fn tidy_all<S: AsRef<str>>(lines: &[S]) -> Vec<String> {
    lines
        .iter()
        .map(|l| tidy(l.as_ref()).into_owned())
        .filter(|l| !l.is_empty())
        .collect()
}

unitTests:
use std::borrow::Cow;

fn is_borrowed(c: &Cow<'_, str>) -> bool { matches!(c, Cow::Borrowed(_)) }

test("results", || {
    check_eq(tidy("  hello   there\t world ").as_ref(), "hello there world");
    check_eq(tidy("“quoted” and ‘single’").as_ref(), "\"quoted\" and 'single'");
    check_eq(tidy("fine as it is").as_ref(), "fine as it is");
    check_eq(tidy("   ").as_ref(), "");
});

test("borrowing when possible", || {
    let s = String::from("  just trimmed  ");
    let t = tidy(&s);
    check(is_borrowed(&t));
    check_eq(t.as_ptr(), s[2..].as_ptr());
    check(is_borrowed(&tidy("already tidy")));
    check(!is_borrowed(&tidy("two  spaces")));
    check(!is_borrowed(&tidy("tab\there")));
});

test("tidy_all accepts any string type", || {
    check_eq(tidy_all(&["  a  b ", "", "   ", "c"]), vec!["a b".to_string(), "c".to_string()]);
    check_eq(tidy_all(&vec![String::from("x\t\ty")]), vec!["x y".to_string()]);
});

